/**
 * Decks marketplace catalogue (WP19-31). `catalog.json`, `files/*.mixaipack` and
 * `previews/*.png` are generated by `node apps/mixai/packs-src/build.mjs` (Skin SDK, signed
 * with the official key at build time) and served by app/api/decks/packs/**. The contract is
 * apps/mixai/src/bridge/marketplace.ts (MarketCatalog / MarketPack).
 *
 * Files are read from disk by known catalogue id only (never from a request path); the
 * standalone build ships them through `outputFileTracingIncludes` in next.config.ts.
 */
import "server-only";
import { readFile } from "node:fs/promises";
import path from "node:path";
import catalogJson from "./catalog.json";

export interface MarketPack {
    id: string;
    name: string;
    version: string;
    kind: "skin" | "layout" | "bundle" | "controller";
    author: string;
    description: string;
    pro: boolean;
    trust: "official" | "verified" | "community" | "unsigned";
    size: number;
    sha256: string;
    previewUrl: string | null;
    tags: string[];
    updatedAt: string;
}

export interface MarketCatalog {
    v: 1;
    generatedAt: string;
    packs: MarketPack[];
}

export const catalog = catalogJson as MarketCatalog;

/** Directory holding the generated pack data (cwd = apps/web in dev, build and the Docker image). */
export function packsDir(): string {
    return path.join(process.cwd(), "src", "lib", "decks-packs");
}

/** Look up a pack by id. Only ids present in the catalogue resolve. */
export function findPack(id: string): MarketPack | null {
    return catalog.packs.find((p) => p.id === id) ?? null;
}

export async function readPackFile(pack: MarketPack): Promise<Buffer> {
    return readFile(path.join(packsDir(), "files", `${pack.id}.mixaipack`));
}

export async function readPreview(pack: MarketPack): Promise<Buffer> {
    return readFile(path.join(packsDir(), "previews", `${pack.id}.png`));
}
